mapper.select:
	/* saleson.shop.statistics.locgov.StatisticsLocgovMapper.getLocgovLikeListTotal */
	SELECT COUNT(*)
	  FROM ( SELECT GL.UPPER_LOCGOV_CODE
	                ,GL.LOCGOV_CODE, GL.LOCGOV_NM
	                ,COUNT(USER_ID) AS LIKE_CNT
	           FROM G_INTRST_LOCGOV GIL, G_LOCGOV GL
	          WHERE GIL.LOCGOV_CODE = GL.LOCGOV_CODE

	            AND GL.LOCGOV_CODE = #{shLocgovCode}

   	          GROUP BY GL.UPPER_LOCGOV_CODE, GL.LOCGOV_CODE
   	        )

/* saleson.shop.statistics.locgov.StatisticsLocgovMapper.getLocgovLikeList */
SELECT GL.UPPER_LOCGOV_CODE ,(SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GL.UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y') AS UPPER_LOCGOV_NM ,GL.LOCGOV_CODE ,GL.LOCGOV_NM ,COUNT(USER_ID) AS LIKE_CNT FROM G_INTRST_LOCGOV GIL, G_LOCGOV GL WHERE GIL.LOCGOV_CODE = GL.LOCGOV_CODE
AND GL.LOCGOV_CODE = #{shLocgovCode}
GROUP BY GL.UPPER_LOCGOV_CODE, GL.LOCGOV_CODE ORDER BY LIKE_CNT DESC

		/* saleson.shop.statistics.locgov.StatisticsLocgovMapper.getLikeCntByLocgov */
		SELECT COUNT(USER_ID) AS LIKE_CNT
		       ,COUNT( CASE WHEN YEAR(REGIST_DE) = #{shCntrYear} THEN 1 END ) AS YEAR_LIKE_CNT
          FROM G_INTRST_LOCGOV GIL, G_LOCGOV GL
         WHERE GIL.LOCGOV_CODE = GL.LOCGOV_CODE
           AND GL.LOCGOV_CODE = #{shLocgovCode}

/* saleson.shop.statistics.locgov.StatisticsLocgovMapper.statisticsLocgovLikeByMonth */
SELECT MONTH(REGIST_DE) AS CNTR_MONTH
	   ,COUNT(USER_ID) AS LIKE_CNT
  FROM G_INTRST_LOCGOV
 WHERE YEAR(REGIST_DE) = #{shCntrYear}
   AND LOCGOV_CODE = #{shLocgovCode}
 GROUP BY CNTR_MONTH
